insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"the_kingdoms_worst_day_q01_fenn_done","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\the_kingdoms_worst_day.yaml","source_metadata":{}},{"key":"the_kingdoms_worst_day_q01_fenn_start","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\the_kingdoms_worst_day.yaml","source_metadata":{}},{"key":"the_kingdoms_worst_day_q02_will_done","speaker_external_id":"Blacksmith","source_path":"_registry\\dialogues\\the_kingdoms_worst_day.yaml","source_metadata":{}},{"key":"the_kingdoms_worst_day_q02_will_start","speaker_external_id":"Blacksmith","source_path":"_registry\\dialogues\\the_kingdoms_worst_day.yaml","source_metadata":{}},{"key":"the_kingdoms_worst_day_q03_painter_done","speaker_external_id":"Painter","source_path":"_registry\\dialogues\\the_kingdoms_worst_day.yaml","source_metadata":{}},{"key":"the_kingdoms_worst_day_q03_painter_start","speaker_external_id":"Painter","source_path":"_registry\\dialogues\\the_kingdoms_worst_day.yaml","source_metadata":{}},{"key":"the_kingdoms_worst_day_q04_guide_start","speaker_external_id":"Mountain Guide","source_path":"_registry\\dialogues\\the_kingdoms_worst_day.yaml","source_metadata":{}},{"key":"the_kingdoms_worst_day_q04_maya_done","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\the_kingdoms_worst_day.yaml","source_metadata":{}},{"key":"the_kingdoms_worst_day_q04_professor_done","speaker_external_id":"Professor Crazy","source_path":"_registry\\dialogues\\the_kingdoms_worst_day.yaml","source_metadata":{}},{"key":"the_kingdoms_worst_day_q04_professor_start","speaker_external_id":"Professor Crazy","source_path":"_registry\\dialogues\\the_kingdoms_worst_day.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"the_kingdoms_worst_day_q01_fenn_done","locale":"he","line_order":0,"content":"מצוין! השמות חזרו: חפצים יכולים להיות gate, key, book או crown.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q01_fenn_done","locale":"he","line_order":1,"content":"עכשיו אנחנו יודעים מה נמצא בשער. אבל אף אחד בבית המלאכה לא יודע מה לעשות.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q01_fenn_done","locale":"he","line_order":2,"content":"לכו אל Will ב־BuildersHome וחפשו את פעולות העבודה שאבדו.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q01_fenn_start","locale":"he","line_order":0,"content":"אסון בשער! רשימת היום איבדה את שמות האנשים, המקומות והחפצים.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q01_fenn_start","locale":"he","line_order":1,"content":"אני קורא ל־gate \"כף גדולה\", ל־key \"מקל קטן\", ול־crown \"קערה נוצצת\". זה לא עוזר לאף אחד.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q01_fenn_start","locale":"he","line_order":2,"content":"התאימו nouns לתמונות, ואז כתבו באנגלית את המילה שפירושה מפתח.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q02_will_done","locale":"he","line_order":0,"content":"עבודה טובה! עכשיו ברור ש־fix ו־open הן פעולות, ולא שמות של אנשים.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q02_will_done","locale":"he","line_order":1,"content":"הסדן התעורר, אבל Painter אומרת שכל הציורים נראים אותו דבר.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q02_will_done","locale":"he","line_order":2,"content":"לכו אליה ליד The Sunspire Tree והשיבו לממלכה את מילות התיאור.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q02_will_start","locale":"he","line_order":0,"content":"הכלים שלי שלמים, אבל ה־verbs נעלמו מהפתקים. הפטיש שלי מנסה לתקן את עצמו.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q02_will_start","locale":"he","line_order":1,"content":"צריך להחזיר לפעולות את האותיות החסרות, ואז לבנות משפט קצר שמסביר מה אני עושה.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q02_will_start","locale":"he","line_order":2,"content":"אחרי התרגול חזרו אליי. אם המשפט ברור, אפילו הסדן יפסיק לנחור.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q03_painter_done","locale":"he","line_order":0,"content":"נהדר! adjectives כמו big, small, bright ו־dark שוב מתארים את הדברים הנכונים.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q03_painter_done","locale":"he","line_order":1,"content":"עכשיו נשאר לחבר שם, פעולה ותיאור במשפט אחד. Professor Crazy מחכה במגדל.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q03_painter_start","locale":"he","line_order":0,"content":"הציורים שלי איבדו את ה־adjectives. כל עץ נראה גדול, קטן, בהיר וחשוך בבת אחת.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q03_painter_start","locale":"he","line_order":1,"content":"השלימו את האות החסרה במילות התיאור, ואז בנו משפט שמתאר דבר אחד בצורה ברורה.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q03_painter_start","locale":"he","line_order":2,"content":"אם התיאור יהיה נכון, סוף סוף אדע איזה ציור למסור למלך.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_guide_start","locale":"he","line_order":0,"content":"בדרך אל המגדל חשוב שההודעה תהיה מובנת גם בלי לראות את המכונה.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_guide_start","locale":"he","line_order":1,"content":"הקשיבו למשפט, אמרו אותו באנגלית בקול, ונסו שוב אם המיקרופון לא שמע בבירור.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_guide_start","locale":"he","line_order":2,"content":"אחרי שתצליחו, חזרו אל Teacher Maya עם לוח היום המתוקן.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_maya_done","locale":"he","line_order":0,"content":"הצלחתם להציל את היום הגרוע ביותר בממלכה! שמות, פעולות ותיאורים שוב עובדים יחד.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_maya_done","locale":"he","line_order":1,"content":"זיהיתם nouns, השתמשתם ב־verbs וב־adjectives, בניתם משפטים ואמרתם הודעה חדשה בקול.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_maya_done","locale":"he","line_order":2,"content":"Words make sentences, and sentences make the kingdom work. קבלו 10 מטבעות על ההצלה.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_professor_done","locale":"he","line_order":0,"content":"המשפטים מסודרים! המכונה מצאה שוב מי עושה מה ואיזה דבר מתואר.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_professor_done","locale":"he","line_order":1,"content":"קחו את ההודעה אל Mountain Guide ב־TowerOfLostVigil. הוא יבדוק את ההגייה.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_professor_start","locale":"he","line_order":0,"content":"המכונה שלי הדפיסה את לוח היום, אבל היא ערבבה nouns, verbs ו־adjectives.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_professor_start","locale":"he","line_order":1,"content":"בנו שני משפטי חירום חדשים לפי התרגום בעברית. אם המשפטים ברורים, הממלכה תבין אותם.","line_format":"plain_text"},{"dialogue_key":"the_kingdoms_worst_day_q04_professor_start","locale":"he","line_order":2,"content":"אחר כך Mountain Guide יבדוק אם אפשר לומר את ההודעה בקול בלי שהמכונה תתפוצץ.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
